import { createPool, Pool } from 'generic-pool';
import * as net from 'net';

interface ConnectionConfig {
  host: string;
  port: number;
  metadata?: Record<string, unknown>;
}

interface PooledConnection {
  socket: net.Socket;
  id: string;
  config: ConnectionConfig;
}

const DEFAULT_CONFIG: ConnectionConfig = {
  host: 'localhost',
  port: 5432,
  metadata: {}
};

class ConfigRegistry {
  private store: Record<string, any> = {};

  constructor() {
    this.store = Object.create(null);
  }

  applyDefaults(target: Record<string, any>, defaults: Record<string, any>): Record<string, any> {
    const result: Record<string, any> = {};
    for (const key of Object.keys(defaults)) {
      result[key] = target[key] !== undefined ? target[key] : defaults[key];
    }
    for (const key of Object.keys(target)) {
      if (result[key] === undefined) {
        result[key] = target[key];
      }
    }
    return result;
  }

  deepMerge(target: any, source: any): any {
    if (typeof source !== 'object' || source === null) return source;
    if (typeof target !== 'object' || target === null) target = {};

    const output = Array.isArray(source) ? [...source] : { ...target };

    for (const key of Object.keys(source)) {
      const srcVal = source[key];
      if (typeof srcVal === 'object' && srcVal !== null && !Array.isArray(srcVal)) {
        output[key] = this.deepMerge(output[key], srcVal);
      } else {
        output[key] = srcVal;
      }
    }
    return output;
  }

  registerConfig(namespace: string, userConfig: Record<string, any>): void {
    const merged = this.applyDefaults(userConfig, DEFAULT_CONFIG);
    this.store[namespace] = merged;
  }

  getConfig(namespace: string): any {
    return this.store[namespace] || null;
  }

  updateMetadata(namespace: string, patch: Record<string, any>): void {
    const config = this.store[namespace];
    if (!config) return;
    config.metadata = this.deepMerge(config.metadata || {}, patch);
  }
}

class ConnectionPoolManager {
  private pools: Map<string, Pool<PooledConnection>> = new Map();
  private registry: ConfigRegistry;

  constructor(registry: ConfigRegistry) {
    this.registry = registry;
  }

  createConnectionPool(namespace: string): Pool<PooledConnection> {
    const config = this.registry.getConfig(namespace);
    if (!config) throw new Error(`No config for namespace: ${namespace}`);

    const pool = createPool<PooledConnection>({
      create: async () => {
        const socket = new net.Socket();
        await new Promise<void>((resolve, reject) => {
          socket.connect(config.port, config.host, () => resolve());
          socket.on('error', reject);
        });
        return { socket, id: Math.random().toString(36).slice(2), config };
      },
      destroy: async (conn) => {
        conn.socket.destroy();
      }
    }, { max: 10, min: 2 });

    this.pools.set(namespace, pool);
    return pool;
  }
}

function parseCliArgs(argv: string[]): Record<string, any> {
  const result: Record<string, any> = {};
  for (let i = 0; i < argv.length; i++) {
    if (argv[i].startsWith('--')) {
      const key = argv[i].slice(2);
      const value = argv[i + 1] && !argv[i + 1].startsWith('--') ? argv[i + 1] : 'true';
      if (value !== 'true') i++;

      const parts = key.split('.');
      let current = result;
      for (let j = 0; j < parts.length - 1; j++) {
        if (!current[parts[j]] || typeof current[parts[j]] !== 'object') {
          current[parts[j]] = {};
        }
        current = current[parts[j]];
      }
      current[parts[parts.length - 1]] = tryParseValue(value);
    }
  }
  return result;
}

function tryParseValue(val: string): any {
  if (val === 'true') return true;
  if (val === 'false') return false;
  if (/^\d+$/.test(val)) return parseInt(val, 10);
  try { return JSON.parse(val); } catch { return val; }
}

async function main() {
  const registry = new ConfigRegistry();
  const poolManager = new ConnectionPoolManager(registry);

  const args = parseCliArgs(process.argv.slice(2));
  const namespace = args.namespace || 'default';
  delete args.namespace;

  registry.registerConfig(namespace, { host: args.host, port: args.port });

  if (args.metadata) {
    registry.updateMetadata(namespace, args.metadata);
  }

  try {
    const pool = poolManager.createConnectionPool(namespace);
    const conn = await pool.acquire();
    console.log(`Connected: ${conn.id} to ${conn.config.host}:${conn.config.port}`);
    await pool.release(conn);
    await pool.drain();
    await pool.clear();
  } catch (err: any) {
    console.error(`Connection failed: ${err.message}`);
  }
}

main().catch(console.error);
